/// <summary>
/// This class will enable the button for batchjobs which contain specific controller classes
/// </summary>
[ExtensionOf(formDataSourceStr(BatchJobEnhanced,BatchJob))]
internal final class METBatchJobEnhanced_Extension
{
}

Method.Source:
/// <summary>
/// This class enables the buttton <c>CopyBatchFinRecord</c> for the batch jobs which are containing specific controllers
/// </summary>
/// <returns>int</returns>
public int active()
{
    int             ret             = next active();
    Batch           batchTask;
    BatchJob        batchJobRecord  = this.cursor();
    FormRun         formRun         = this.formRun();
    FormControl     copyBatchBtn    = formRun.design().controlName(formControlStr(BatchJobEnhanced, METCopyBatchFinRecord));
    container       targetClasses   = [ classStr(TAMRebateCreateTransController), classStr(TAMRebatePostController), classStr(METVendorRebateOffRemittanceCalcController), classStr(METVFDVarVendClaimJournalController),
                                        classStr(METTAMRebateCreateTransController_Provision), classStr(METTAMRebateCreateTransController_Rebate), classStr(METTAMRebateCreateTransController_WriteOff),
                                        classStr(METTAMRebatePostController_Provision), classStr(METTAMRebatePostController_Rebate), classStr(METTAMRebatePostController_WriteOff), classStr(METRebateCombinedController)
                                       ];

    //Query to check batch job contain any one of the specific controller class
    select firstonly ClassNumber, RecId from batchTask
            where batchTask.BatchJobId == batchJobRecord.RecId;

    copyBatchBtn.visible(batchTask.RecId && conFind(targetClasses, batchTask.className()));

    return ret;
}
